specs=[dict(id='chuchitisch-kaiserschmarrn',name='Kaiserschmarrn',source='http://chuchitisch.ch/recipes/103',author='Hannes und Martina',provider='Chuchitisch',license='CC BY-SA 3.0',licenseUrl='https://creativecommons.org/licenses/by-sa/3.0/',servings=2,prep=5,cook=15,cuisine='Österreichisch',allergens=['Ei','Gluten','Milch'],rows=[row('Ei',4,'Stück','171287',200),row('Weizenmehl',40,'g','169761'),row('Milch',60,'ml','171265'),row('Salz',.5,'g',None),row('Zucker',20,'g','169655'),row('Butter',20,'g','173430')],notes=['Original für 2 Personen: 4 Eier, 4 EL Mehl, 4 EL Milch, 1 Prise Salz; Zucker und Butter ohne Mengenangabe.','Umrechnung: 1 Ei ohne Schale = 50 g, 1 EL Mehl = 10 g, 1 EL Milch = 15 ml, 1 Prise Salz = 0.5 g. Zucker 20 g insgesamt und Butter 20 g sind ergänzte RESERVE-Richtmengen, keine Originalangaben.'],steps=['Eier, Mehl, Milch und Salz in einer Schüssel zu einem glatten Teig verrühren; die Hälfte des Zuckers einrühren.','Butter in einer beschichteten Pfanne bei mittlerer Hitze schmelzen lassen und den Teig hineingiessen.','Backen, bis die Unterseite fest ist; den Teig mit einem Holzlöffel in mundgerechte Stücke zerteilen.','Die Stücke wiederholt vorsichtig wenden und fertig backen, bis sie innen vollständig gestockt und aussen goldbraun sind.','Mit dem restlichen Zucker bestreuen und warm servieren.'],equipment=['Schüssel','Schneebesen','Beschichtete Bratpfanne','Holzlöffel'],doneness='Die Stücke sind goldbraun und innen vollständig gestockt; es ist kein flüssiger Eierteig mehr sichtbar.',photo=False),dict(id='wikibooks-griessbrei-milch',name='Grießbrei mit Milch',source='https://de.wikibooks.org/w/index.php?title=Kochbuch/_Grießbrei&oldid=854992',author='Wikibooks-Mitwirkende (siehe Versionsgeschichte)',provider='Wikibooks',license='CC BY-SA 4.0',licenseUrl='https://creativecommons.org/licenses/by-sa/4.0/',servings=4,prep=5,cook=25,cuisine='Deutschsprachig',allergens=['Gluten','Milch'],rows=[row('Weichweizengriess',125,'g','168933'),row('Milch',1000,'ml','171265'),row('Salz',.5,'g',None),row('Zucker',100,'g','169655'),row('Butter',30,'g','173430')],notes=['Original für 4 Personen; die Buttervariante wird verwendet. Optionale Eier, Vanillezucker, Zitrone und Garnituren sind nicht Bestandteil dieser Fassung.','1 Prise Salz = 0.5 g. Milch vereinfacht mit 1 ml = 1 g berechnet. Weichweizengriess mit USDA Semolina, unenriched angenähert (andere Weizensorte).','Das Foto zeigt zusätzlich Fruchtkompott: ausschliesslich Serviervorschlag, nicht im Rezept oder in den Nährwerten enthalten.'],steps=['Milch und Salz in einem grossen Topf unter Rühren zum Kochen bringen.','Den Griess langsam unter ständigem Rühren einrieseln lassen, damit keine Klümpchen entstehen.','Die Hitze reduzieren und den Brei bei schwacher Hitze unter regelmässigem Rühren quellen lassen, bis er cremig angedickt ist.','Zucker und Butter einrühren, bis sich beides gleichmässig im Brei verteilt hat.','Vom Herd nehmen und warm servieren. Ist der Brei zu fest, schluckweise etwas Milch ergänzen; die Mengen ändern sich dadurch.'],equipment=['Kochtopf','Schneebesen','Kochlöffel'],doneness='Der Griess ist weich aufgequollen und der Brei cremig; am Topfboden ist nichts angebrannt.',photo=True),dict(id='wikibooks-milchreis',name='Milchreis-Grundrezept',source='https://de.wikibooks.org/w/index.php?title=Kochbuch/_Milchreis&oldid=797101',author='Wikibooks-Mitwirkende (siehe Versionsgeschichte)',provider='Wikibooks',license='CC BY-SA 4.0',licenseUrl='https://creativecommons.org/licenses/by-sa/4.0/',servings=2,prep=5,cook=40,cuisine='Deutschsprachig',allergens=['Milch'],rows=[row('Rundkornreis',225,'g','168879'),row('Milch',1000,'ml','171265'),row('Salz',.5,'g',None),row('Zucker',25,'g','169655')],notes=['Original für 2–3 Personen; gemäss Nutzerregel werden 2 Personen als Basis verwendet.','Original nennt 200–250 g Rundkornreis; diese RESERVE-Fassung verwendet ausdrücklich 225 g als gewählte mittlere Menge. Keine exakte Originalangabe.','2 EL Zucker = 25 g, 1 Prise Salz = 0.5 g. Milch vereinfacht mit 1 ml = 1 g; Rundkornreis mit USDA weissem Mittelkornreis angenähert.','Das Foto ist ein Serviervorschlag und nicht nachweislich nach diesem konkreten Rezept zubereitet.'],steps=['Milch mit Rundkornreis und Salz in einen ausreichend grossen Topf geben und unter Rühren aufkochen.','Zucker einrühren und die Hitze so weit reduzieren, dass die Milch nur leicht köchelt.','Den Reis im offenen Topf etwa 40 Minuten bei geringer Hitze garen; regelmässig bis zum Topfboden umrühren.','Sobald die Reiskörner weich sind und der Brei cremig ist, vom Herd nehmen. Falls nötig etwas Milch ergänzen.','Kurz ruhen lassen, nochmals umrühren und warm servieren. Zusätzliche Beilagen sind in den Nährwerten nicht enthalten.'],equipment=['Kochtopf','Kochlöffel'],doneness='Die Reiskörner sind weich ohne harten Kern und von cremiger Milch umgeben.',photo=True)]
